#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int d[61] = {0};
    int e[61] = {0};

    for (int i = 0; i < n; i++) {
        int m;
        char l;
        scanf("%d %c", &m, &l);
        if (l == 'D') {
            d[m]++;
        } else {
            e[m]++;
        }
    }

    int total_pares = 0;
    for (int i = 30; i <= 60; i++) {
        if (d[i] < e[i]) {
            total_pares += d[i];
        } else {
            total_pares += e[i];
        }
    }

    printf("%d\n", total_pares);

    return 0;
}
